package world

import (
	"embed"
	"encoding/json"
	"math"
	"sort"
	"strings"
	"unicode"

	"golang.org/x/text/unicode/norm"

	"github.com/myahse/babi-life/backend/internal/game"
)

// Every place of a commune, from OpenStreetMap: the maquis, boutiques,
// couturiers, salons, churches, mosques, schools, pharmacies… named on the
// map inside the commune's boundary (thousands in Yopougon). They're
// generated by tools/places/build.mjs and embedded here. They aren't in the
// world payload (it would weigh megabytes): the app asks for those around
// the Sim (GET /places). The hand-made places of world.go stay the
// commune's landmarks; a map point that is one of them is left out.

//go:embed osm/*.json
var osmFiles embed.FS

// OSMSource is the provenance shared by every place from the map.
var OSMSource = &game.Source{
	Status:  game.StatusPartial,
	URLs:    []string{"https://www.openstreetmap.org/copyright", "https://openfreemap.org/"},
	Checked: game.Checked,
	Note:    "Nom, type et position d'après OpenStreetMap (contributeurs, ODbL). Vérifié par la communauté, pas un par un par le jeu ; le type de lieu du jeu est déduit de celui de la carte.",
}

type osmFile struct {
	Commune string  `json:"commune"`
	Fetched string  `json:"fetched"`
	Places  [][]any `json:"places"` // id, name, kind, lat, lng, quarter, type
}

// MapPlace is a place from the map, as the app gets it.
type MapPlace struct {
	ID      string  `json:"id"`
	Name    string  `json:"name"`
	Kind    string  `json:"kind"`
	Lat     float64 `json:"lat"`
	Lng     float64 `json:"lng"`
	Quarter string  `json:"quarter,omitempty"`
	// Type is what the map calls it (kiosk, tailor, christian…).
	Type string `json:"type,omitempty"`
}

var (
	mapPlaces  = map[string][]MapPlace{} // by commune
	mapByID    = map[string]MapPlace{}
	mapCommune = map[string]string{} // place id → commune id
	mapFetched = map[string]string{}
)

func init() {
	entries, err := osmFiles.ReadDir("osm")
	if err != nil {
		panic(err)
	}
	for _, e := range entries {
		raw, err := osmFiles.ReadFile("osm/" + e.Name())
		if err != nil {
			panic(err)
		}
		var f osmFile
		if err := json.Unmarshal(raw, &f); err != nil {
			panic("osm/" + e.Name() + ": " + err.Error())
		}
		cm, ok := communeByID(f.Commune)
		if !ok {
			panic("osm/" + e.Name() + ": unknown commune " + f.Commune)
		}
		for _, row := range f.Places {
			p := MapPlace{ID: row[0].(string), Name: row[1].(string), Kind: row[2].(string), Lat: row[3].(float64), Lng: row[4].(float64), Quarter: row[5].(string)}
			if t, ok := row[6].(string); ok {
				p.Type = t
			}
			if _, ok := game.Kinds[p.Kind]; !ok {
				panic("osm/" + e.Name() + ": unknown kind " + p.Kind + " for " + p.ID)
			}
			if curated(cm, p) {
				continue
			}
			mapPlaces[f.Commune] = append(mapPlaces[f.Commune], p)
			mapByID[p.ID] = p
			mapCommune[p.ID] = f.Commune
		}
		mapFetched[f.Commune] = f.Fetched
	}
}

func communeByID(id string) (Commune, bool) {
	for _, c := range Cities {
		for _, cm := range c.Communes {
			if cm.ID == id {
				return cm, true
			}
		}
	}
	return Commune{}, false
}

// curated: the map point is one of the commune's hand-made places (same
// kind of name, within 400 m): the hand-made one stays, with its sources.
func curated(cm Commune, p MapPlace) bool {
	pw := nameWords(p.Name)
	for _, c := range cm.Places {
		if distKm(c.Lat, c.Lng, p.Lat, p.Lng) > 0.4 {
			continue
		}
		cw := nameWords(c.Name)
		if len(cw) == 0 || len(pw) == 0 {
			continue
		}
		shared := 0
		for w := range cw {
			if pw[w] {
				shared++
			}
		}
		if float64(shared) >= 0.6*float64(min(len(cw), len(pw))) {
			return true
		}
	}
	return false
}

var stopWords = map[string]bool{"de": true, "du": true, "des": true, "la": true, "le": true, "les": true, "l": true, "d": true, "et": true, "a": true, "au": true, "yopougon": true}

func nameWords(s string) map[string]bool {
	t := norm.NFD.String(strings.ToLower(s))
	out := map[string]bool{}
	for _, w := range strings.FieldsFunc(t, func(r rune) bool { return !unicode.IsLetter(r) && !unicode.IsDigit(r) }) {
		w = strings.Map(func(r rune) rune {
			if unicode.Is(unicode.Mn, r) {
				return -1
			}
			return r
		}, w)
		if w != "" && !stopWords[w] {
			out[w] = true
		}
	}
	return out
}

func distKm(lat1, lng1, lat2, lng2 float64) float64 {
	dy := (lat2 - lat1) * 111.32
	dx := (lng2 - lng1) * 111.32 * math.Cos((lat1+lat2)/2*math.Pi/180)
	return math.Hypot(dx, dy)
}

// MapPlacesNear: a commune's map places within r km of a point, nearest
// first, at most limit of them.
func MapPlacesNear(commune string, lat, lng, r float64, limit int) []MapPlace {
	type near struct {
		p MapPlace
		d float64
	}
	var all []near
	for _, p := range mapPlaces[commune] {
		if d := distKm(lat, lng, p.Lat, p.Lng); d <= r {
			all = append(all, near{p, d})
		}
	}
	sort.Slice(all, func(i, j int) bool { return all[i].d < all[j].d })
	if len(all) > limit {
		all = all[:limit]
	}
	out := make([]MapPlace, len(all))
	for i, n := range all {
		out[i] = n.p
	}
	return out
}

// SearchMapPlaces: a commune's map places whose name or quarter has all
// these words, at most limit of them (for "Où aller ?").
func SearchMapPlaces(commune, q string, limit int) []MapPlace {
	want := nameWords(q)
	if len(want) == 0 {
		return nil
	}
	var out []MapPlace
	for _, p := range mapPlaces[commune] {
		have := nameWords(p.Name + " " + p.Quarter)
		ok := true
		for w := range want {
			found := false
			for h := range have {
				if strings.HasPrefix(h, w) {
					found = true
					break
				}
			}
			if !found {
				ok = false
				break
			}
		}
		if ok {
			out = append(out, p)
			if len(out) >= limit {
				break
			}
		}
	}
	return out
}

// MapPlaceByID: one map place.
// Commissariats: the commune's police stations on the map (« Commissariat
// du 16ᵉ Arrondissement »…), gendarmeries left out, by name.
func Commissariats(commune string) []MapPlace {
	var out []MapPlace
	for _, p := range mapPlaces[commune] {
		if p.Kind == "police" && strings.Contains(strings.ToLower(p.Name), "commissariat") {
			out = append(out, p)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

func MapPlaceByID(id string) (MapPlace, bool) {
	p, ok := mapByID[id]
	return p, ok
}

// MapPlaceCount: how many map places a commune has.
func MapPlaceCount(commune string) int { return len(mapPlaces[commune]) }

// mapPlace finds a map place by id, as a world Place.
func mapPlace(id string) (City, Commune, Place, bool) {
	p, ok := mapByID[id]
	if !ok {
		return City{}, Commune{}, Place{}, false
	}
	for _, c := range Cities {
		for _, cm := range c.Communes {
			if cm.ID == mapCommune[id] {
				return c, cm, Place{ID: p.ID, Name: p.Name, Kind: p.Kind, Lat: p.Lat, Lng: p.Lng, Quarter: p.Quarter, Real: true, Source: OSMSource}, true
			}
		}
	}
	return City{}, Commune{}, Place{}, false
}
